"""Build the curated dossier from manually reviewed, bounded responses. No fetching."""
import json
from pathlib import Path
P=Path(__file__).parent
E=P/'evidence'
def meta(n):return json.loads((E/(n+'.json')).read_text())
def source(n,claim):
 m=meta(n);return dict(url=m['url'],claim=claim,evidence_path=m['evidence_path'])
def size(value,unit,date,n,quality,note):
 m=meta(n);return dict(value=value,unit=unit,date=date,source_url=m['url'],evidence_path=m['evidence_path'],quality=quality,note=note)
def lib(id,name,rec,scope,siz,q,robot,title,author,rid,detail,isbn,holdings,access,count,match='exact_title',family='PMB',notes=None):
 m=meta(q);r=meta(robot+'-robots');d=meta(detail)
 text=m.get('payload',{}).get('user_query') if m.get('payload') else 'Forced adjustment'
 return dict(id='cod-'+id,name=name,recommendation=rec,scope=scope,size=siz,
 platform=dict(family=family,name='PMB with custom Laravel Livewire frontend' if family=='PMB/custom' else 'PMB; version not established',proof='Institutional page names PMB; custom catalog URL parameters q and notice declared in public Livewire URL effects.' if family=='PMB/custom' else 'PMB footer and public OPAC form/routes; bibliography and local copy table returned.',evidence_path=m['evidence_path']),
 query=dict(text=text,method=m['method'],url=m['url'],payload=m['payload'],checked_at_utc=m['checked_at_utc'],http_status=m['status'],effective_url=m['effective_url'],result_count=count,count_note='Displayed result count; broad token matching can include unrelated records. Not a collection or edition count.',match_type=match,evidence_path=m['evidence_path'],metadata_path=m['metadata_path']),
 books=[dict(title=title,author=author,record_id=str(rid),record_url=d['url'],isbn=isbn,holdings=holdings,evidence_path=d['evidence_path'])],
 robots=dict(url=r['url'],status=r['status'],checked_at_utc=r['checked_at_utc'],evidence_path=r['metadata_path'],decision='no_published_rules' if r['status']==404 else 'allowed_path',note='HTTP 404 does not grant reuse rights.' if r['status']==404 else ('Wildcard allows paths, Crawl-delay 10 seconds.' if robot=='mikanda' else 'Checked public catalog path; CEPAS /livewire/ is disallowed and was not requested.')),
 reader_access=access,integration=dict(existing_adapter='new custom frontend adapter' if family=='PMB/custom' else 'PMB family generalization required; existing PMB integration is deployment-specific',needs=['Preserve record/edition and institution identity','Preserve excluded-from-loan, consultation-only and loaned statuses','Return could-not-check on failures; do not infer not-held']+(notes or []),blockers=['Not integrated or tested in the live application; reuse rights and current operational access not established'],live_app_tested=False))
libs=[]
libs.append(lib('cepas','Centre d’Études Pour l’Action Sociale — Bibliothèque CEPAS','verified_target','One institutional library, Kinshasa; do not count its Mikanda representation separately',size(45000,'volumes (more than)','undated page, checked 2026-11-15','cepas-home','official','Official page states more than 45,000 books and 1,600 periodical titles; catalog separately displays 34,165 indexed notices, including articles.'),'cepas-exact','cepas','Forced adjustment [the expert collapse in sub-saharan Africa]','Roy Culpeper',13789,'cepas-exact',None,'1 copy; number 22305; ECO.5.J.68; Bibliothèque du CEPAS; Economie du développement; Consultation sur place; Livre','Public online search. Physical consultation and paid subscriptions described on official library page; current visitor conditions not tested.',1,family='PMB/custom',notes=['Use public GET q/notice URL mapping; do not call robots-disallowed /livewire/','Catalog subtitle contains “expert”, transcribed as returned rather than silently corrected']))
libs.append(lib('upc','Université Protestante au Congo — Bibliothèque Universitaire Centrale','verified_target','One university library verified by UPC copy in the Mikanda shared catalog; Mikanda network is not separately counted',size(29400,'volumes, approximately','2015','ifla-upc','primary institutional conference paper','UPC librarian reports ~29,400 volumes; historical scale only. Current official page confirms service to five faculties.'),'mikanda-upc-query','mikanda','La publicité est dans le film : placement de produits et stratégie de marque au cinéma, dans les chansons, dans les jeux vidéo ...','Jean-Marc Lehu; Christian Polge (preface)',2744,'upc-detail','978-2-7081-3643-4','1 copy; barcode 0101032; 659.1 LEH 2007; UPC; récent; Exclu du prêt','Public catalog; this copy is excluded from lending. Current university page directs readers to the library for visitor/loan rules.',1,notes=['Enforce Mikanda 10-second per-origin crawl delay','Validate local institution from holdings, never from author/publisher or a branch selector alone']))
libs.append(lib('ulpgl','Université Libre des Pays des Grands Lacs — Bibliothèque universitaire, Goma','verified_target','One university network across its faculties; BIFAD copy proven, no faculty counted separately',size(32246,'books, including 2,000 ebooks','undated page, checked 2026-11-15','ulpgl-collections','official','Total is mixed physical/digital and must not be presented as 32,246 physical books. Two-campus network stated.'),'opac-ulpgl-query-2-results','opac-ulpgl','Sociologie des médias','Rémy Rieffel',7182,'ulpgl-detail','978-2-7298-0596-8','1 copy; BU0005955; 302.23 RIE; Livre; BIFAD; Généralités; Disponible','Public OPAC. Official pages disagree on whether on-site consultation is free or paid; borrowing needs registration. Do not settle fee conflict from search results.',82,notes=['Official library catalog page links opac.bu-ulpgl.net; do not substitute catalogue.bu-ulpgl.net, which has demo-like content','First POST search_result then follow returned POST more_results form; preserve semantic payload and fresh session']))
libs.append(lib('udbl','Université Don Bosco de Lubumbashi — library network (Theologicum holding)','verified_target','One UDBL institutional catalog; observed holding is Bibliothèque Theologicum. Do not count the separate Theologicum hostname as another institution',size(None,'university library network','current official site, checked 2026-11-15','udbl-library-source','institutional proxy','Official university library page names Saint François de Sales and Ladrille sites; catalog holds Theologicum material. No defensible collection total was found.'),'udbl-title-final','udbl','Manon Lescaut','Antoine François Prévost',78384,'udbl-detail',None,'1 copy; LL 54.005; 809.3; Livre; Bibliothèque Theologicum; Exclu du prêt','Anonymous electronic catalog is described as accessible to visitors; the selected physical copy is excluded from lending. Physical entry eligibility unverified.',2,notes=['Exact title retry followed broad unrelated “Analyse microéconomique” results and a zero-result phrase; these do not show book absence','Official legal template reserves database/content rights; public lookup is not bulk reuse permission']))
libs.append(lib('sgnc','Service Géologique National du Congo — geological and mining documentation network','verified_target','One shared ministry/agency documentation network; CTCPM book holding proven. CAMI/SGMINES/MISEDERE/SGN-C selectors are not separately verified institutions',size(5,'named agency collections in the shared catalog','2026-11-15','sgnc-home','institutional proxy','Catalog names CAMI, CTCPM, MISEDERE, SGMINES and SGN-C; not five separately tested collections and not a book total.'),'sgnc-query-3-results','sgnc','haut- Uele : trésor touristique','Jean Omasombo Tshonda (director of publication)',215,'sgnc-detail','978-2-87106-578-4','1 copy; barcode 1001; DP247; papier/numérique; CTCPM; BIBLIOTHEQUE; Disponible. Separate public PDF link also listed.','Anonymous catalog. Physical access and borrowing rules unverified; this is a book with a local copy, not merely a repository PDF.',21,match='related_titles',notes=['Query is title fragment “haut- Uele”; result includes the matching book and maps/reports','Fresh anonymous session required: GET form, POST search_result, then returned POST more_results with freshly emitted csrf_token','Replace nonce each run; captured request metadata is evidence, not a durable replay credential','Generic PMB vendor address in footer is not the library location; use holder CTCPM and institutional addresses']))
libs.append(lib('ifrdc','Institut Français RDC — shared médiathèque catalog (Lubumbashi holding)','verified_target','One shared four-city catalog; only IF Lubumbashi physical holding is verified. Kinshasa, Bukavu and Goma are not counted independently',size(4,'city catalog views (network proxy)','2026-11-15','ifrdc-home','institutional proxy','Catalog exposes Kinshasa, Lubumbashi, Bukavu and Goma. This does not establish each city is operational or collection size; Cairn ebook totals are not local holdings.'),'ifrdc-query2','ifrdc','Droit de la concurrence','Marie-Anne Frison-Roche; Jean-Christophe Roda',31397,'ifrdc-detail','978-2-247-20572-1','1 copy; LU304447; 343 FRI; LIVRE; IF Lubumbashi; Documentaire Adulte; Document pouvant être prêté; Sorti jusqu’au 21/11/2026','Public OPAC; Lubumbashi official page describes paid annual memberships and two loanable books for two weeks. Selected copy is on loan, not available.',2439,notes=['Start fresh anonymous form at index.php?lvl=index&opac_view=2; carry csrf_token in memory to normal POST','Do not assume the root/default view or union results prove every city','A prior quoted Le petit prince returned zero; not evidence of absence']))
libs.append(lib('karibuni','Bibliothèque Karibuni, Kinshasa','reserve','One community/study library proven by Karibuni holding within Mikanda; network not separately counted',size(None,'unquantified study/community library','2026-11-15','mikanda-members','institutional network source','Mikanda official site describes its 20th anniversary, educational activities and staff/volunteers; scale is insufficient to call it a major national collection.'),'mikanda-query','mikanda','Le Petit Prince','Antoine de Saint-Exupéry',161504,'karibuni-detail',None,'1 copy; BK 1757; R SAI P; Karibuni; indéterminé; Disponible','Public catalog; community/study library. Physical visitor and loan eligibility not tested.',3063,notes=['Enforce per-origin 10-second delay','Only the first returned exact-title book is cited; other keyword results must not be treated as that work']))
priorities=[]
def priority(name,claim,url,outcome,evidence):priorities.append(dict(name=name,size_claim=claim,source_url=url,outcome=outcome,evidence_path=evidence))
def pr(name,claim,n,outcome):m=meta(n);priority(name,claim,m['url'],outcome,m['evidence_path'])
pr('Bibliothèque nationale du Congo, Kinshasa','National legal-deposit and heritage mandate is the scale proxy; no current physical collection total verified.','acp-national','No public physical-book OPAC established; retain as major priority, not a successful lookup.')
pr('Université de Kinshasa (UNIKIN)','Official faculty page describes central library plus 10 faculty and 6 research/large-school libraries; institutional network proxy.','unikin-faculty','Koha installation documented historically; 2023 study labels koha.unikin.cd as intranet. No internal probing; current public page has no book search.')
pr('Université de Lubumbashi (UNILU)','Official page: central >29,000 volumes and 4,300 periodicals; faculty collections 11,200 and 6,350 periodicals; central +14 faculties +4 documentation centers. Units/date are not nationally comparable.','unilu-home','Substantial collection identified; no supported public book-query route found on reviewed institutional page.')
pr('Université de Kisangani (UNIKIS)','Official central library service within the major public university; numerical collection total unknown.','unikis-services','Services page is not an OPAC; no returned physical-book search. Do not confuse UNIKIS with Kindu/UNIKI or Université Libre de Kisangani.')
pr('Université Pédagogique Nationale (UPN)','Central university library serving the national pedagogical university; institutional proxy, no numeric total.','upn-library','Official central virtual library links theses and DEA dissertations, not a verified physical-book catalog. Astria news does not establish print holdings.')
pr('Université Catholique du Congo (UCC)','Approximately 90,100 volumes reported in 2015 institutional conference study; historical, not current total.','ifla-upc','Mikanda lists UCC but exploratory title produced no result; no UCC holding verified. Do not count selector or UCC-as-publisher as collection evidence.')
pr('Université Catholique de Bukavu (UCB)','Current official page describes thousands of books, journals and physical/digital collections; institutional proxy.','ucb-current','No public physical-book search exposed. Earlier indexed 38,295-volume document returned HTTP 404; current claim remains qualitative.')
for l in libs[:3]:priority(l['name'],l['size']['note'],l['size']['source_url'],'Verified query; '+l['scope'],l['size']['evidence_path'])
for l in libs[3:6]:priority(l['name'],l['size']['note'],l['size']['source_url'],'Verified query using explicit institutional/network scale proxy; '+l['scope'],l['size']['evidence_path'])
priority('CEDESURK — interuniversity documentation center','Interuniversity documentation and capacity-building center; 120 reading places reported by institutional cooperation publication (2016), not a current collection count.','https://orbi.uliege.be/bitstream/2268/188554/1/Livre%20Pacodel.pdf','Historical Koha endpoint koha.cedesurk.org robots HTTP503; stopped without searching. Important shared-service prospect.','evidence/discovery-s4.json')
blocked=[]
def block(name,url,reason,path):blocked.append(dict(name=name,url=url,reason=reason,evidence_path=path))
for row in priorities[:7]:block(row['name'],row['source_url'],row['outcome'],row['evidence_path'])
block('CEDESURK','http://koha.cedesurk.org/robots.txt','Robots HTTP503: unresolved. No automated catalog search attempted.','evidence/cedesurk-robots.json')
block('CENCO library','https://cencordc.org/robots.txt','HTTP200 verification challenge, not ordinary HTML fallback. Stopped.','evidence/cenco-robots.html')
block('Université Loyola du Congo / Saint-Pierre Canisius','https://www.uloyola.cd/bibliotheque/','Current page describes resources and subscriptions but no public physical catalog. Historical bibliospcanisius.org robots returned 403 (no approved upstream IPv4); stopped.','evidence/loyola-library.html')
block('Université du Lac Albert — Marbella','https://pmb.unilac.cd/opac_css/','Officially linked public OPAC exists but has generic template; PMB landing displays only 223 notices. Not prioritized as a substantial collection; no book-query success claimed.','evidence/unilac-opac.html')
block('Université Protestante de Lubumbashi (UPL)','https://bibliotheque.upl-univ.ac/catalogue','Catalog landing lists 1,949 mixed records and public Livewire search UI. No specific book query executed; landing results are not a success.','evidence/upl-home.html')
block('ULPGL alternate catalog hostname','https://catalogue.bu-ulpgl.net/opac_css/','Contains PMB demo-like Bibliobus/Loire material. Official library page instead links opac.bu-ulpgl.net, used for successful physical-copy verification; alternate is not counted.','evidence/ulpgl-home.html')
block('Theologicum separate hostname','https://biblio-theologicum.org/pmb/opac_css/','Robots redirects to ordinary PMB homepage. Not separately searched/counted because UDBL catalog explicitly returns Theologicum holdings; avoid double counting.','evidence/theologicum-robots.html')
market=dict(summary='DR Congo (COD) has public universities, national/legal-deposit services, confessional institutions, specialist documentation centers and diplomatic/community reading services. Current national library/system totals are not available from this research. PMB is the best evidenced reusable public-catalog family in this feasibility sample; Koha is historically documented at UNIKIN/CEDESURK, and CD-ISIS is a documented predecessor at UPC. This is not LMS market share.',platform_strategy='Build a general PMB public-form/record/holding adapter with deployment profiles and strict institution mapping, then a separate CEPAS GET frontend adapter. Prioritize Mikanda shared-catalog institution mappings and SGN-C/IFRDC network profiles. Keep Koha as a secondary discovery/reactivation prospect until legitimate public endpoints can be verified. Preserve physical-book status and do not treat electronic databases, theses repositories or nominal catalog views as print holdings.',adoption_evidence=[dict(claim='Observed PMB catalog forms, records and physical holdings at Mikanda (UPC/Karibuni), ULPGL, UDBL, SGN-C and Institut Français RDC; CEPAS explicitly identifies a PMB-backed custom frontend.',scope='Seven successful collection units across six public catalog origins, feasibility selected',date='2026-11-15',source_url='https://katalog.mikanda.info/pmb/opac_css/'),dict(claim='UPC librarian reports prior CD-ISIS catalog and migration to PMB; roughly 29,400 volumes in 2015.',scope='UPC only; historical institutional paper, not national adoption',date='2015-09-14',source_url=meta('ifla-upc')['url']),dict(claim='UNIKIN implementation case documents Koha and a central/faculty network.',scope='UNIKIN historical case, published 2008; not live operational validation',date='2008',source_url=meta('ifla-unikin')['url']),dict(claim='Published study identifies UNIKIN Koha route as intranet, and gives CEDESURK Koha route.',scope='Cahiers Economiques et Sociaux 2023, referring to 2017 catalog sources; indexed page 103',date='2023',source_url=meta('ced-study')['url'])],network_opportunities=[dict(name='Réseau Mikanda',scope='Shared PMB catalog with independently named institutional locations, plus training/mutualization',source_url='https://mikanda.info/',verification='UPC and Karibuni physical copies actually returned. Other selectors, including UCC, do not prove operational collection access.',integration_implication='One shared PMB profile can expose distinct institutions only when returned holdings prove the mapping. Do not count union network plus constituents.'),dict(name='SGN-C geological/mining documentation network',scope='Five agency selectors; only CTCPM physical book holding observed',source_url='https://sgnc.pmb.cd/opac_css/',verification='Haut-Uele book and CTCPM copy returned; network treated as one unit.',integration_implication='PMB with fresh anonymous CSRF session; separate map/report types from books.'),dict(name='Institut Français RDC médiathèques',scope='Four city views; only IF Lubumbashi holding observed',source_url='https://mediatheques-ifrdc.org/',verification='Droit de la concurrence returned with IF Lubumbashi on-loan copy.',integration_implication='One network profile initially; validate each city before offering separately filtered results.'),dict(name='CEDESURK',scope='Interuniversity documentation/capacity-building organization',source_url='https://orbi.uliege.be/bitstream/2268/188554/1/Livre%20Pacodel.pdf',verification='Historical role sourced; catalog robots 503 unresolved today.',integration_implication='Institutional shared-service opportunity, not a verified endpoint.')])
limitations=['No national largest-ten ranking established;14 priorities are not a ranked size league table.','Seven observed successes: six selected candidates and one reserve; the ten-substantial-query goal remains four selected candidates short.','UDBL, SGN-C and IFRDC selection rests on explicit institutional/network proxies, not audited book totals; do not present them as the six largest libraries.','Only UPC/Karibuni are proven within Mikanda; CTCPM within SGN-C; IF Lubumbashi within IFRDC. Unqueried selectors do not establish holdings.','Historical counts, mixed book/ebook totals, periodicals and indexed notices are different units and must not be summed.','Normal anonymous sessions were memory-only; no accounts, cookies, authentication or reader actions were saved/performed. CSRF fields in bounded raw responses/request metadata are historical form evidence and must be freshly obtained.','One unsuccessful Mikanda UCC exploratory form/query/result chain did not enforce its 10-second crawl delay. Subsequent successful UPC sequence was corrected with explicit 10-second wait. This deviation is retained rather than represented as fully compliant.','UCC programme PDF was bounded to 2 MB of an 8 MB file and cannot validate its indexed 100,000-volume claim; use the complete 2015 primary paper for historical scale.','Public lookup is not permission to bulk reuse bibliographic databases; reader entry/borrowing rules and operational reliability need separate confirmation.','Research only: no product configuration, adapter, outreach or deployment changes; live_app_tested=false throughout.']
sources=[source('cepas-home','Official collection scale, PMB identification and consultation rules'),source('ifla-upc','Historical UPC/UCC scale and UPC CD-ISIS-to-PMB evidence'),source('ifla-unikin','Historical UNIKIN Koha implementation'),source('unikin-faculty','UNIKIN institutional library network'),source('unilu-home','UNILU collection quantities and network structure'),source('unikis-services','UNIKIS central library service'),source('upn-library','UPN central virtual library routes are theses/dissertations'),source('ucb-current','Current qualitative UCB library scale'),source('acp-national','National library mandate, director interview'),source('ulpgl-collections','Mixed physical/digital book total and two campuses'),source('ulpgl-catalog-link','Official provenance of opac.bu-ulpgl.net'),source('udbl-library-source','Official UDBL network and catalog link; rights language'),source('sgnc-home','Agency network and PMB platform'),source('ifrdc-home','Four-city shared catalog'),source('ifrdc-size','IF Lubumbashi membership and circulation rules'),source('mikanda-members','Mikanda role and Karibuni background'),dict(url='https://rel.bib.umontreal.ca/bibliotheques-a-l-international3/chapter/republique-democratique-du-congo/',claim='Scoped secondary country synthesis: fragmented urban/public/institutional provision; stale national statistics. Direct HTTP403; indexed text retained, not a catalog success.',evidence_path='evidence/discovery-s10.json'),dict(url=meta('ced-study')['url'],claim='2023 article page 103 explicitly labels UNIKIN catalog intranet and cites CEDESURK; use indexed extraction for this passage.',evidence_path='evidence/discovery-s8.json')]
chains={
 'cod-ulpgl':['opac-ulpgl-query-2-form','opac-ulpgl-query-2','opac-ulpgl-query-2-results'],
 'cod-sgnc':['sgnc-query-3-form','sgnc-query-3','sgnc-query-3-results'],
 'cod-ifrdc':['ifrdc-query2-form','ifrdc-query2'],
 'cod-upc':['mikanda-upc-query-form','mikanda-upc-query']
}
for item in libs:
 if item['id'] in chains:
  item['query']['request_chain']=[dict(metadata_path='evidence/'+n+'.json',method=meta(n)['method'],url=meta(n)['url']) for n in chains[item['id']]]
data=dict(country='Democratic Republic of the Congo',country_code='COD',research_date_utc='2026-11-15',status='complete',counts=dict(observed_successes=len(libs),selected=6,reserves=1,major_priorities=len(priorities),selected_shortfall=4),market=market,major_library_priorities=priorities,libraries=libs,blocked_or_unverified=blocked,limitations=limitations,sources=sources)
(P/'findings.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
